        echo '<p>You do not have permission to access your Artiste post.</p>';
    }
}
add_action('um_profile_tab_artiste', 'um_artiste_tab_content');

// Handle form submissions for creating, updating, and deleting 'Artiste' posts
function handle_artiste_forms() {
    if (isset($_POST['create_artiste']) || isset($_POST['update_artiste']) || isset($_POST['delete_artiste'])) {
        check_admin_referer('artiste_nonce', 'artiste_nonce');

        if (isset($_POST['create_artiste'])) {
            $post_title = sanitize_text_field($_POST['post_title']);
            $post_content = wp_kses_post($_POST['post_content']);
            $meta_data = $_POST['meta_data'];

            $new_post_id = wp_insert_post(array(
                'post_title' => $post_title,
                'post_content' => $post_content,
                'post_status' => 'publish',
                'post_author' => get_current_user_id(),
                'post_type' => 'artiste' // Replace with your post type name
            ));

            foreach ($meta_data as $key => $value) {
                update_post_meta($new_post_id, $key, sanitize_text_field($value));
            }

            wp_redirect(get_permalink($new_post_id));
            exit();
        } elseif (isset($_POST['update_artiste'])) {
            $post_id = intval($_POST['post_id']);
            $post_title = sanitize_text_field($_POST['post_title']);
            $post_content = wp_kses_post($_POST['post_content']);
            $meta_data = $_POST['meta_data'];

            wp_update_post(array(
                'ID' => $post_id,
                'post_title' => $post_title,
                'post_content' => $post_content
            ));

            foreach ($meta_data as $key => $value) {
                update_post_meta($post_id, $key, sanitize_text_field($value));
            }

            wp_redirect(get_permalink($post_id));
            exit();
        } elseif (isset($_POST['delete_artiste'])) {
            $post_id = intval($_POST['post_id']);
            wp_delete_post($post_id, true);

            wp_redirect(home_url('/my-account/artiste/'));
            exit();
        }
    }
}
add_action('wp_loaded', 'handle_artiste_forms');

// Register the 'edit_artiste' capability for specific roles
function register_edit_artiste_capability() {
    $role = get_role('contributor'); // Replace 'contributor' with your desired role
    if ($role) {
        $role->add_cap('edit_artiste');
    }
}
add_action('admin_init', 'register_edit_artiste_capability');
