function handle_create_artiste_form() {
    if (isset($_POST['create_artiste'])) {
        // Security check
        check_admin_referer('create_artiste_nonce', 'create_artiste_nonce');

        $post_title = sanitize_text_field($_POST['post_title']);
        $post_content = wp_kses_post($_POST['post_content']);
        $meta_data = $_POST['meta_data'];

        // Insert the new post
        $new_post_id = wp_insert_post(array(
            'post_title' => $post_title,
            'post_content' => $post_content,
            'post_status' => 'publish',
            'post_author' => get_current_user_id(),
            'post_type' => 'artiste'
        ));

        // Save the meta data
        foreach ($meta_data as $key => $value) {
            update_post_meta($new_post_id, $key, sanitize_text_field($value));
        }

        // Redirect after creation
        wp_redirect(get_permalink($new_post_id));
        exit();
    }
}
add_action('wp_loaded', 'handle_create_artiste_form');

// Function to handle the update of an existing 'Artiste' post
function handle_update_artiste_form() {
    if (isset($_POST['update_artiste'])) {
        // Security check
        check_admin_referer('update_artiste_nonce', 'update_artiste_nonce');

        $post_id = intval($_POST['post_id']);
        $post_title = sanitize_text_field($_POST['post_title']);
        $post_content = wp_kses_post($_POST['post_content']);
        $meta_data = $_POST['meta_data'];

        // Update the post
        wp_update_post(array(
            'ID' => $post_id,
            'post_title' => $post_title,
            'post_content' => $post_content
        ));

        // Update the meta data
        foreach ($meta_data as $key => $value) {
            update_post_meta($post_id, $key, sanitize_text_field($value));
        }

        // Redirect after update
        wp_redirect(get_permalink($post_id));
        exit();
    }
}
add_action('wp_loaded', 'handle_update_artiste_form');

// Function to handle the deletion of an 'Artiste' post
