from machine import Pin, Timer, ADC, I2C, PWM
import ssd1306

# Define the FIFO class
class Fifo:
    def __init__(self, size):
        self.size = size
        self.queue = []

    def put(self, item):
        if len(self.queue) >= self.size:
            self.queue.pop(0)
        self.queue.append(item)

    def get(self):
        if not self.empty():
            return self.queue.pop(0)
        else:
            return None

    def empty(self):
        return len(self.queue) == 0

# Initialize I2C and OLED display
def init_oled():
    try:
        i2c = I2C(1, scl=Pin(15), sda=Pin(14))
        oled = ssd1306.SSD1306_I2C(128, 64, i2c)
        return oled
    except Exception as e:
        print(f"Failed to initialize I2C or OLED: {e}")
        raise SystemExit

# Configure ADC for sampling
def init_adc(pin):
    try:
        adc = ADC(Pin(pin))
        return adc
    except Exception as e:
        print(f"Failed to configure ADC: {e}")
        raise SystemExit

# Main program loop
def main():
    oled = init_oled()
    adc = init_adc(26)  # Example pin, adjust according to your setup

    samples = Fifo(size=50)
    window_size = 100
    window = []
    sampling_period_ms = 4  # Update this value as desired
    update_interval = 500  # Update OLED every 500ms

    last_update_time = utime.ticks_ms()

    try:
        while True:
            # Sample ADC and add to FIFO
            try:
                sample = adc.read_u16()  # Adjust according to your ADC usage
                samples.put(sample)
                print(f"Sample added: {sample}")  # Debugging info
            except Exception as e:
                print(f"Failed to read ADC: {e}")

            if not samples.empty():
                sample = samples.get()
                window.append(sample)
                print(f"Window updated: {len(window)}")  # Debugging info

                # Remove the oldest sample if the window is full
                if len(window) > window_size:
                    window.pop(0)

                if len(window) == window_size:
                    # Calculate EMA incrementally
                    ema_value = 0
                    if len(window) > 1:
                        alpha = 0.1
                        ema_value = alpha * window[-1] + (1 - alpha) * window[-2]
                    else:
                        ema_value = window[-1]

                    # Find peaks in the signal array
                    peaks = []
                    for i in range(1, len(window) - 1):
                        if window[i] > window[i-1] and window[i] > window[i+1] and window[i] > 50:
                            peaks.append(i)
                    peak_intervals = [peaks[i+1] - peaks[i] for i in range(len(peaks)-1)]

                    # Update OLED display only periodically
                    current_time = utime.ticks_ms()
                    if utime.ticks_diff(current_time, last_update_time) >= update_interval:
                        try:
                            oled.fill(0)
                            oled.text('Peaks:', 0, 0)
                            oled.text(str(peak_intervals), 0, 10)
                            oled.show()
                            last_update_time = current_time
                        except Exception as e:
                            print(f"Failed to update OLED: {e}")

            try:
                utime.sleep_ms(sampling_period_ms)
            except KeyboardInterrupt:
                print("Interrupted during sleep. Continuing…")

    except KeyboardInterrupt:
        print("Exiting program…")
    finally:
        # Clean-up code here if necessary
        pass

if __name__ == "__main__":
    main()
