    SSL* ssl = BIO_get_ssl(bio, NULL);
    if (!ssl) {
        std::cerr << "Failed to get SSL from BIO." << std::endl;
        BIO_free_all(bio);
        SSL_CTX_free(ctx);
        return false;
    }

    // Connect SSL
    if (SSL_connect(ssl) <= 0) {
        std::cerr << "Failed to establish SSL connection." << std::endl;
        BIO_free_all(bio);
        SSL_CTX_free(ctx);
        return false;
    }

    // Prepare POST request
    std::string request = "POST /path HTTP/1.1\r\n";
    request += "Host: " + serviceAddress + "\r\n";
    request += "Content-Type: application/x-www-form-urlencoded\r\n";
    request += "Content-Length: " + std::to_string(postData.size()) + "\r\n\r\n";
    request += postData;

    // Send request
    if (BIO_write(bio, request.c_str(), request.size()) <= 0) {
        std::cerr << "Failed to send POST request." << std::endl;
        BIO_free_all(bio);
        SSL_CTX_free(ctx);
        return false;
    }

    // Read response
    char buffer[4096];
    int bytesRead = 0;
    do {
        bytesRead = BIO_read(bio, buffer, sizeof(buffer));
        if (bytesRead > 0) {
            response.append(buffer, bytesRead);
        }
    } while (bytesRead > 0);

    // Clean up
    BIO_free_all(bio);
    SSL_CTX_free(ctx);

    return true;
