std::string DecryptDescriptor(const std::string& encryptedDescriptor, const std::string& privateKey) {
    BIO *keybio = BIO_new_mem_buf(privateKey.c_str(), -1);
    EVP_PKEY *pkey = PEM_read_bio_PrivateKey(keybio, NULL, NULL, NULL);

    BIO *cipherBio = BIO_new_mem_buf(encryptedDescriptor.c_str(), -1);
    BIO *decryptBio = BIO_new(BIO_f_base64());
    BIO_push(decryptBio, cipherBio);

    int decryptedLength;
    unsigned char *decryptedData = nullptr;
    BIO_read(decryptBio, decryptedData, BIO_pending(decryptBio));

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, nullptr, nullptr))
        throw std::runtime_error("Failed to initialize decryption context.");

    int decryptedLen;
    EVP_DecryptUpdate(ctx, decryptedData, &decryptedLen, encryptedDescriptor.data(), encryptedDescriptor.size());
    EVP_DecryptFinal_ex(ctx, decryptedData + decryptedLen, &decryptedLength);

    BIO_free_all(decryptBio);
    EVP_CIPHER_CTX_free(ctx);
    EVP_PKEY_free(pkey);

    return std::string(static_cast<char*>(decryptedData), decryptedLen + decryptedLength);
